// LÜME ad: the clips in the brief's order, each trimmed to its line, long
// pauses inside a line shortened (micro-dissolve), 9-frame crossfades
// between clips. Music fills every gap without dialogue and ducks under it.
const SPEECH = [
  [86, 225],
  [243, 315],
  [391, 570],
  [609, 891],
  [908, 1569],
  [1585, 2616],
] as const;

const musicVolume = (f: number, total: number) => {
  let duck = 0;
  for (const [a, b] of SPEECH) {
    duck = Math.max(
      duck,
      interpolate(f, [a - 10, a, b, b + 12], [0, 1, 1, 0], {
        extrapolateLeft: "clamp",
        extrapolateRight: "clamp",
      }),
    );
  }
  const fadeInOut = interpolate(f, [0, 10, total - 24, total], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  return (0.36 - duck * 0.27) * fadeInOut;
};

